<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useMemberStore } from '../stores/member'
import { contactApi, type Conversation } from '../services/contact'
import AppHeader from '../components/AppHeader.vue'
import MemberGate from '../components/MemberGate.vue'
const route=useRoute(),member=useMemberStore(),conversation=ref<Conversation|null>(null),content=ref(''),error=ref(''),loading=ref(false),sending=ref(false)
let generation=0, loadVersion=0, timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{timer=setInterval(()=>{if(document.visibilityState==='visible'&&!sending.value)void load()},10000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
async function load(){const token=member.token, id=String(route.params.id),version=generation,request=++loadVersion;if(!member.loggedIn)return;loading.value=true;error.value='';try{const result=await member.privateCall(t=>contactApi.get(t,id));if(version===generation&&token===member.token&&request===loadVersion)conversation.value=result}catch(e){if(version===generation&&token===member.token&&request===loadVersion)error.value=e instanceof Error?e.message:'加载失败'}finally{if(version===generation&&token===member.token&&request===loadVersion)loading.value=false}}
async function send(){const token=member.token,id=String(route.params.id),version=generation,text=content.value.trim();if(!token||!text||sending.value)return;sending.value=true;error.value='';try{await member.privateCall(t=>contactApi.send(t,id,text));if(version===generation&&token===member.token){if(content.value.trim()===text)content.value='';await load()}}catch(e){if(version===generation&&token===member.token)error.value=e instanceof Error?e.message:'发送失败'}finally{if(version===generation&&token===member.token)sending.value=false}}
watch([()=>member.token,()=>route.params.id],()=>{generation++;loadVersion++;conversation.value=null;content.value='';error.value='';loading.value=false;sending.value=false;void load()},{immediate:true,flush:'sync'})
</script>
<template><AppHeader title="联系" back/><main class="page conversation-page"><MemberGate v-if="!member.loggedIn" title="登录后查看消息"/><template v-else><p class="notice">模拟房源 · 请与对方协商看房时间和地点。</p><p v-if="loading&&!conversation" role="status">正在加载…</p><div v-if="error" role="alert" class="error">{{ error }} <button @click="load">重试</button></div><template v-if="conversation"><div class="heading"><strong>{{ member.profile?.id===conversation.ownerId?conversation.tenantNickname:conversation.ownerNickname }}</strong><span>{{ conversation.listingId }} · 模拟房源</span></div><div class="messages" aria-live="polite"><p v-if="!conversation.messages?.length" class="muted">还没有消息，先聊聊看房安排吧。</p><div v-for="message in conversation.messages" :key="message.id" class="message" :class="{mine:message.senderId===member.profile?.id}"><p>{{ message.content }}</p><time>{{ new Date(message.createdAt).toLocaleString('zh-CN') }}</time></div></div><form class="composer" @submit.prevent="send"><label class="sr-only" for="message-content">输入消息</label><textarea id="message-content" v-model="content" maxlength="1000" rows="2" placeholder="输入消息，协商看房安排"/><button class="primary" :disabled="sending||!content.trim()">{{ sending?'发送中…':'发送' }}</button></form></template></template></main></template>
<style scoped>.conversation-page{padding-top:18px;padding-bottom:calc(110px + env(safe-area-inset-bottom))}.notice{background:var(--surface);padding:14px;border-radius:14px;font-size:12px;line-height:1.7}.heading{display:flex;flex-direction:column;gap:6px;padding:22px 0;border-bottom:1px solid var(--line)}.heading span{font-size:12px;color:var(--muted)}.messages{min-height:250px;display:flex;flex-direction:column;gap:16px;padding:24px 0}.message{align-self:flex-start;max-width:85%}.message.mine{align-self:flex-end;text-align:right}.message p{background:var(--surface);padding:12px 15px;border-radius:14px;white-space:pre-wrap;overflow-wrap:anywhere;text-align:left}.message.mine p{background:var(--ink);color:white}.message time{display:block;font-size:11px;color:var(--muted);margin-top:5px}.composer{display:flex;gap:10px;align-items:end}.composer textarea{flex:1;min-width:0;border:1px solid var(--line);border-radius:12px;padding:12px;resize:vertical;font:inherit}.composer button{width:auto;min-width:72px}.error{margin-top:12px;color:#a33;font-size:13px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}</style>
